<?php require __DIR__.'/../includes/functions.php'; require_login('student'); $uid=user()['id']; $q=db()->prepare('SELECT * FROM student_profiles WHERE user_id=?');$q->execute([$uid]);$p=$q->fetch() ?: []; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); if(empty($_POST['consent'])){$error='برای ذخیره اطلاعات، تأیید رضایت الزامی است.';}else{$sql='INSERT INTO student_profiles (user_id,grade,study_field,strengths,difficult_subjects,academic_goal,learning_style,interests,current_mood,communication_preference,study_resources,support_request,student_note,national_id,birth_date,gender,address,emergency_contact,emergency_phone,health_notes,allergies,parent_name,parent_phone,parent_relation,household_status,primary_caregiver,caregiver_phone,consent,consent_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE grade=VALUES(grade),study_field=VALUES(study_field),strengths=VALUES(strengths),difficult_subjects=VALUES(difficult_subjects),academic_goal=VALUES(academic_goal),learning_style=VALUES(learning_style),interests=VALUES(interests),current_mood=VALUES(current_mood),communication_preference=VALUES(communication_preference),study_resources=VALUES(study_resources),support_request=VALUES(support_request),student_note=VALUES(student_note),national_id=VALUES(national_id),birth_date=VALUES(birth_date),gender=VALUES(gender),address=VALUES(address),emergency_contact=VALUES(emergency_contact),emergency_phone=VALUES(emergency_phone),health_notes=VALUES(health_notes),allergies=VALUES(allergies),parent_name=VALUES(parent_name),parent_phone=VALUES(parent_phone),parent_relation=VALUES(parent_relation),household_status=VALUES(household_status),primary_caregiver=VALUES(primary_caregiver),caregiver_phone=VALUES(caregiver_phone),consent=1,consent_at=NOW()';db()->prepare($sql)->execute([$uid,$_POST['grade']??'',$_POST['study_field']??'',$_POST['strengths']??'',$_POST['difficult_subjects']??'',$_POST['academic_goal']??'',$_POST['learning_style']??'',$_POST['interests']??'',$_POST['current_mood']??'',$_POST['communication_preference']??'',$_POST['study_resources']??'',$_POST['support_request']??'',$_POST['student_note']??'',$_POST['national_id']??'',$_POST['birth_date']?:null,$_POST['gender']??'',$_POST['address']??'',$_POST['emergency_contact']??'',$_POST['emergency_phone']??'',$_POST['health_notes']??'',$_POST['allergies']??'',$_POST['parent_name']??'',$_POST['parent_phone']??'',$_POST['parent_relation']??'',$_POST['household_status']??'',$_POST['primary_caregiver']??'',$_POST['caregiver_phone']??'']);flash('اطلاعات شما با موفقیت ذخیره شد.');redirect('/student/index.php');}} $m=db()->prepare('SELECT * FROM messages WHERE student_id=? ORDER BY created_at DESC');$m->execute([$uid]); layout_start('پنل دانش‌آموز'); ?><div class="page-head"><div><p class="eyebrow">پنل دانش‌آموز</p><h1>سلام <?=e(user()['name'])?></h1></div><a class="button secondary" href="<?=e(url('/student/message.php'))?>">پیام جدید</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="card form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><h2>فرم اطلاعات محرمانه</h2><p class="muted full">فقط مواردی را وارد کنید که با اشتراک آن‌ها راحت هستید. موارد سلامت برای حمایت بهتر و در صورت نیاز ارجاع به مشاور استفاده می‌شوند.</p><label>کد ملی<input name="national_id" value="<?=e($p['national_id']??'')?>"></label><label>تاریخ تولد<input type="date" name="birth_date" value="<?=e($p['birth_date']??'')?>"></label><label>جنسیت<select name="gender"><option value="">انتخاب کنید</option><option <?=($p['gender']??'')==='دختر'?'selected':''?>>دختر</option><option <?=($p['gender']??'')==='پسر'?'selected':''?>>پسر</option></select></label><label>نسبت والد/سرپرست<input name="parent_relation" value="<?=e($p['parent_relation']??'')?>"></label><label>نام والد/سرپرست<input name="parent_name" value="<?=e($p['parent_name']??'')?>"></label><label>تلفن والد/سرپرست<input name="parent_phone" inputmode="tel" value="<?=e($p['parent_phone']??'')?>"></label><div class="full support-box"><h3>شناخت آموزشی و علایق</h3><p class="muted">پاسخ‌ها برای حمایت آموزشی بهتر استفاده می‌شوند و می‌توانید هر موردی را خالی بگذارید.</p><label>پایه تحصیلی<input name="grade" value="<?=e($p['grade']??'')?>"></label><label>رشته یا گرایش<input name="study_field" value="<?=e($p['study_field']??'')?>"></label><label>نقاط قوت من<textarea name="strengths"><?=e($p['strengths']??'')?></textarea></label><label>درس‌هایی که در آن‌ها کمک می‌خواهم<textarea name="difficult_subjects"><?=e($p['difficult_subjects']??'')?></textarea></label><label>هدف تحصیلی امسال<textarea name="academic_goal"><?=e($p['academic_goal']??'')?></textarea></label><label>روش یادگیری مورد علاقه<select name="learning_style"><option value="">انتخاب کنید</option><option <?=($p['learning_style']??'')==='توضیح و گفت‌وگو'?'selected':''?>>توضیح و گفت‌وگو</option><option <?=($p['learning_style']??'')==='مثال و تمرین'?'selected':''?>>مثال و تمرین</option><option <?=($p['learning_style']??'')==='تصویر و نمودار'?'selected':''?>>تصویر و نمودار</option><option <?=($p['learning_style']??'')==='کار گروهی'?'selected':''?>>کار گروهی</option><option <?=($p['learning_style']??'')==='مطالعه مستقل'?'selected':''?>>مطالعه مستقل</option></select></label><label class="full">علایق و استعدادها<textarea name="interests"><?=e($p['interests']??'')?></textarea></label></div><div class="full support-box"><h3>شرایط حمایتی و ارتباط</h3><p class="muted">این بخش اختیاری است و برای فراهم‌کردن حمایت مناسب‌تر طراحی شده است.</p><h3>شرایط حمایتی (اختیاری)</h3><p class="muted">این بخش فقط برای شناخت بهتر نیازهای حمایتی شماست؛ پاسخ ندادن هیچ مشکلی ایجاد نمی‌کند.</p><label>وضعیت زندگی و سرپرستی<select name="household_status"><option value="">انتخاب کنید</option><option value="با هر دو والد زندگی می‌کنم" <?=($p['household_status']??'')==='با هر دو والد زندگی می‌کنم'?'selected':''?>>با هر دو والد زندگی می‌کنم</option><option value="والدین جدا از هم زندگی می‌کنند" <?=($p['household_status']??'')==='والدین جدا از هم زندگی می‌کنند'?'selected':''?>>والدین جدا از هم زندگی می‌کنند</option><option value="یکی از والدین فوت کرده است" <?=($p['household_status']??'')==='یکی از والدین فوت کرده است'?'selected':''?>>یکی از والدین فوت کرده است</option><option value="با یکی از والدین زندگی می‌کنم" <?=($p['household_status']??'')==='با یکی از والدین زندگی می‌کنم'?'selected':''?>>با یکی از والدین زندگی می‌کنم</option><option value="با سرپرست دیگری زندگی می‌کنم" <?=($p['household_status']??'')==='با سرپرست دیگری زندگی می‌کنم'?'selected':''?>>با سرپرست دیگری زندگی می‌کنم</option><option value="ترجیح می‌دهم پاسخ ندهم" <?=($p['household_status']??'')==='ترجیح می‌دهم پاسخ ندهم'?'selected':''?>>ترجیح می‌دهم پاسخ ندهم</option></select></label><label>نام سرپرست اصلی<input name="primary_caregiver" value="<?=e($p['primary_caregiver']??'')?>"></label><label>تلفن سرپرست اصلی<input name="caregiver_phone" inputmode="tel" value="<?=e($p['caregiver_phone']??'')?>"></label><label>حال عمومی این روزها<select name="current_mood"><option value="">انتخاب کنید</option><option>آرام</option><option>نگران</option><option>غمگین</option><option>خسته</option><option>بی‌حوصله</option><option>ترجیح می‌دهم پاسخ ندهم</option></select></label><label>شیوه ارتباط ترجیحی<select name="communication_preference"><option value="">انتخاب کنید</option><option>پیام داخل سامانه</option><option>گفت‌وگوی خصوصی</option><option>با حضور مشاور</option><option>با حضور والد یا سرپرست</option></select></label><label>امکانات مطالعه و اینترنت<select name="study_resources"><option value="">انتخاب کنید</option><option>مناسب است</option><option>گاهی نیاز به حمایت دارم</option><option>نیازمند حمایت جدی هستم</option><option>ترجیح می‌دهم پاسخ ندهم</option></select></label><label>درخواست حمایت<select name="support_request"><option value="">درخواستی ندارم</option><option>پیگیری آموزشی</option><option>گفت‌وگو با مدیر</option><option>گفت‌وگو با مشاور</option><option>کمک برای امکانات آموزشی</option></select></label><label class="full">نکته‌ای که دوست داری بدانیم<textarea name="student_note"><?=e($p['student_note']??'')?></textarea></label></div><label class="full">نشانی<textarea name="address"><?=e($p['address']??'')?></textarea></label><label>تماس اضطراری<input name="emergency_contact" value="<?=e($p['emergency_contact']??'')?>"></label><label>تلفن اضطراری<input name="emergency_phone" inputmode="tel" value="<?=e($p['emergency_phone']??'')?>"></label><label>حساسیت‌ها<textarea name="allergies"><?=e($p['allergies']??'')?></textarea></label><label>نکات سلامت<textarea name="health_notes"><?=e($p['health_notes']??'')?></textarea></label><label class="full checkbox"><input type="checkbox" name="consent" value="1" <?=!empty($p['consent'])?'checked':''?> required> با رضایت خودم، اجازه می‌دهم اطلاعات بالا برای ارتباط و حمایت آموزشی استفاده شود.</label><button class="button full">ذخیره اطلاعات</button></form><section class="card"><h2>پیام‌ها</h2><?php while($x=$m->fetch()):?><article class="message <?=e($x['sender_role'])?>"><small><?=e($x['sender_role']==='admin'?'مدیر سامانه':'من')?> · <?=e($x['created_at'])?></small><p><?=nl2br(e($x['body']))?></p></article><?php endwhile; if(!$m->rowCount()):?><p class="muted">هنوز پیامی وجود ندارد.</p><?php endif;?></section><?php layout_end(); ?>
